import requests, json, sys

webhook = "https://open.feishu.cn/open-apis/bot/v2/hook/39ace5b8-ddf6-4ccf-8912-2c2681c618a4"

card = {
    "msg_type": "interactive",
    "card": {
        "header": {
            "title": {
                "tag": "plain_text",
                "content": "✅ 澳洲冰箱新品监控日报 - 2026年6月24日"
            },
            "template": "blue"
        },
        "elements": [
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**今日 5 品牌均无新品上架或状态变更**\n\n本次为首次基线建立，已将各品牌当前产品清单记录为基线数据。\n\n---\n\n**海信 Hisense** 🔵\n首页最新排序 12 款产品，总计 53 款在售冰箱，涵盖 6 个子品类。\n2026 年款 5 款，2025 年款 8 款。\n\n**美的 Midea** 🟢\n品类页面显示 7 个子品类（French Door / Quad Door / Side by Side / Top Mount / Bottom Mount / Car Fridge / Chest Freezer）。Top Mount 页面为 JS 动态渲染，无法抓取产品列表。\n\n**三星 Samsung** ⚪\n官网使用动态加载，搜索未发现 2026 年澳洲冰箱新品。\n\n**LG** ⚪\n官网有反爬保护，搜索未发现 2026 年澳洲冰箱新品。\n\n**西屋 Westinghouse** 🟡\n首页展示 5 款代表性产品，涵盖 8 个子品类。WHE6874SA 已停产。"
                }
            },
            {
                "tag": "hr"
            },
            {
                "tag": "note",
                "elements": [
                    {
                        "tag": "plain_text",
                        "content": "由 Incaier Agent 自动监控 | 下次汇总：明天下午 3:07"
                    }
                ]
            }
        ]
    }
}

resp = requests.post(webhook, json=card, timeout=15)
result = {"status_code": resp.status_code, "body": resp.json()}
with open(sys.argv[-1], "w", encoding="utf-8") as f:
    json.dump(result, f, ensure_ascii=False, indent=2)
print("status:", resp.status_code, resp.json())

